-- MK Fraud Readiness Score V1 - Phase 10 additive migration
-- Adds the one genuinely missing column found during schema inspection, and seeds a
-- STARTER set of draft report_content_blocks so the report engine has something to
-- select from. Every block below is inserted with status='draft' - none of it is live
-- or client-facing until MK explicitly reviews and approves it (flips status to
-- 'active') via the admin content-block screen. See docs/CONTENT_BLOCKS_REVIEW_NEEDED.md.

alter table public.report_events add column if not exists metadata_json jsonb default '{}'::jsonb;

do $$
declare
  v_methodology_version_id uuid;
begin
  select id into v_methodology_version_id from public.methodology_versions where status = 'active' limit 1;
  if v_methodology_version_id is null then
    raise exception 'No active methodology version found - cannot seed report_content_blocks.';
  end if;

  on conflict do nothing;
end;
$$;
